{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE redtape_db.Maplemonk.redtape_db_flipkart_margin_fact_items as SELECT EAN, SKU, ARTICLE, FLIPKART_CATEGORY, UPPER(FKT.CATEGORY) CATEGORY, SUB_CATEGORY, GENDER, LENGTH_CM, HEIGHT_CM, WIDTH_CM, WEIGHT_KG, VOLUME_WEIGHT, CHARGEABLE_WEIGHT, AVAILABLE_QUANTITY, MRP, COST, TYPE, MULTIPLE, \"DISCOUNT_%\", ROUND(BILL_VALUE,2) BILL_VALUE, \"GST_%\", ROUND(SALE_VALUE,2) SALE_VALUE, ROUND(COALESCE(NEW_GTA_VALUE,0),2) AS TOTAL_GTA, Round(COALESCE(BILL_VALUE, 0) - COALESCE(TOTAL_GTA, 0),2) AS BILL_VALUE_AFTER_GTA, CASE WHEN BILL_VALUE_AFTER_GTA < 2625 THEN 5 ELSE 18 END AS \"GST2_%\", ROUND((BILL_VALUE_AFTER_GTA * 100 / NULLIF(100 + \"GST2_%\", 0)),2) AS SALE_VALUE_AFTER_GTA, ROUND(COALESCE(SALE_VALUE_AFTER_GTA, 0) - COALESCE(COST, 0),2) AS GROSS_MARGIN, ROUND((GROSS_MARGIN / NULLIF(COALESCE(SALE_VALUE_AFTER_GTA,0),0)) * 100,2) AS \"GROSS_MARGIN%\", COMMISSION AS \"COMMISSION_%\", ROUND((COALESCE(BILL_VALUE_AFTER_GTA,0) * COALESCE(\"COMMISSION_%\"/100,0)),2) AS COMMISSION_VALUE, \"COURIER_RET%\", \"CUSTOMER_RET%\", ROUND( (( COALESCE(REV.LOCAL,0) * ZS.LOCAL/100 + COALESCE(REV.ZONAL,0) * ZS.ZONAL/100 + COALESCE(REV.NATIONAL,0) * ZS.NATIONAL/100) * COALESCE(\"CUSTOMER_RET%\",0) / 100) / NULLIF((100 - COALESCE(\"COURIER_RET%\",0) - COALESCE(\"CUSTOMER_RET%\",0)) / 100,0),2) AS REV_FRT, ROUND((5/((100-\"COURIER_RET%\"-\"CUSTOMER_RET%\")/100)),2) AS PACKING, ROUND((COALESCE(SALE_VALUE_AFTER_GTA,0)*(2/100)),2) AS ADVERTISEMET, ROUND((COALESCE(SALE_VALUE_AFTER_GTA,0)*(7.5/100)),2) AS COMMON, ROUND(COALESCE(COMMISSION_VALUE,0)+COALESCE(REV_FRT,0)+COALESCE(PACKING,0)+COALESCE(ADVERTISEMET,0)+COALESCE(COMMON,0),2) AS TOTAL_EXPENSES, ROUND(((COALESCE(TOTAL_EXPENSES,0) / NULLIF(COALESCE(SALE_VALUE_AFTER_GTA,0),0)) * 100),2) AS \"EXPENSES_%\", \"REBATE_%\", ROUND(COALESCE((\"REBATE_%\" / 100.0),0) * COALESCE(BILL_VALUE_AFTER_GTA,0),2) AS REBATE_AMOUNT, ROUND(COALESCE(GROSS_MARGIN,0) - COALESCE(TOTAL_EXPENSES,0) + COALESCE(REBATE_AMOUNT,0),2) AS NET_MARGIN, ROUND((COALESCE(NET_MARGIN,0) / NULLIF(COALESCE(SALE_VALUE_AFTER_GTA,0),0) *100),2) AS \"NET_MARGIN%\" FROM( SELECT ISN.*, ROUND(COALESCE(ISN.MRP,0) / NULLIF(COST, 0),2) AS MULTIPLE, COALESCE(ISN.MRP,0) - (COALESCE(ISN.MRP,0) * \"DISCOUNT_%\" / 100) AS BILL_VALUE, CASE WHEN BILL_VALUE < 2625 THEN 5 ELSE 18 END AS \"GST_%\", (BILL_VALUE * 100 / NULLIF(100 + \"GST_%\", 0)) AS SALE_VALUE, FROM ( SELECT COALESCE(B.EAN,REPLACE(REPLACE(A.EAN_CATEGORY, \'`\', \'\'), \',\', \'\')) EAN, SKU, ARTICLE, LENGTH AS LENGTH_CM, HEIGHT AS HEIGHT_CM, WIDTH AS WIDTH_CM, ROUND(COALESCE(TRY_TO_DOUBLE(WEIGHT),0) / 1000.0,2) AS WEIGHT_KG, ROUND(( COALESCE(TRY_TO_DOUBLE(LENGTH),0) * COALESCE(TRY_TO_DOUBLE(HEIGHT),0) * COALESCE(TRY_TO_DOUBLE(WIDTH),0)) / 5000.0,2) AS VOLUME_WEIGHT, CASE WHEN VOLUME_WEIGHT > WEIGHT_KG THEN VOLUME_WEIGHT ELSE WEIGHT_KG END AS CHARGEABLE_WEIGHT, 80.0 AS \"DISCOUNT_%\", 15.0 AS \"REBATE_%\", ROUND(COALESCE(CR.\"Courier Return%\",25),1) AS \"COURIER_RET%\", ROUND(COALESCE(CR.\"Customer Return%\",11),1) AS \"CUSTOMER_RET%\", CAST(REPLACE(PUR_PRICE, \',\', \'\') AS FLOAT) AS COST, CAST(REPLACE(MRP, \',\', \'\') AS FLOAT) AS MRP, GRADE, A.GENDER, CATEGORY, SUB_CATEGORY, A.TYPE, FLIPKART_CATEGORY, AVAILABLE_QUANTITY FROM MAPLEMONK.REDTAPE_FLIPKART_EAN_MASTER A LEFT JOIN ( SELECT * FROM ( SELECT \"Report Generated Date\"::DATE AS FIRST_DATE, REPLACE(EAN, \'`\', \'\') AS EAN, REPLACE(SKU, \'`\', \'\') AS SKU, REGEXP_REPLACE(REPLACE(SKU,\'`\',\'\'), \'-[^-]*$\', \'\') AS ARTICLE, SUM(\"Available Quantity\") AS AVAILABLE_QUANTITY FROM REDTAPE_DB.MAPLEMONK.EASYECOM_REDTAPE_INVENTORY_SNAPSHOT WHERE \"Report Generated Date\" IS NOT NULL GROUP BY 1,2,3,4) QUALIFY ROW_NUMBER() OVER(PARTITION BY EAN ORDER BY FIRST_DATE DESC) = 1) B ON REPLACE(A.EAN_CATEGORY, \'`\', \'\') = REPLACE(B.EAN, \'`\', \'\') LEFT JOIN( select distinct ACCOUNTING_SKU EAN ,LENGTH ,HEIGHT ,WIDTH ,WEIGHT from maplemonk.easyecom_redtape_product_master) pm on REPLACE(A.EAN_CATEGORY, \'`\', \'\') = REPLACE(PM.EAN, \'`\', \'\') LEFT JOIN( select \"TYPE 2\" TYPE ,GENDER ,\"Courier Return%\" ,\"Customer Return%\" from maplemonk.flipkart_gs_db_courier_and_customer_return where UPPER(gender) != \'ALL\' and TYPE IS NOT NULL) CR ON UPPER(REPLACE(TRIM(A.TYPE), \' \', \'\')) = UPPER(REPLACE(TRIM(CR.TYPE), \' \', \'\')) AND UPPER(TRIM(A.GENDER)) = UPPER(TRIM(CR.GENDER)) ) ISN ) FKT LEFT JOIN ( SELECT VERTICAL ,LOWER_PRICE ,UPPER_PRICE ,LOWER_WEIGHT ,UPPER_WEIGHT ,NEW_GTA_VALUE FROM MAPLEMONK.FLIPKART_REDTAPE_NEW_TOTAL_GTA) GTA ON LOWER(FKT.FLIPKART_CATEGORY) = LOWER(GTA.VERTICAL) AND FKT.BILL_VALUE BETWEEN GTA.LOWER_PRICE AND GTA.UPPER_PRICE AND FKT.CHARGEABLE_WEIGHT BETWEEN GTA.LOWER_WEIGHT AND GTA.UPPER_WEIGHT LEFT JOIN ( SELECT CATEGORY, VERTICAL, COMMISSION, LOWER_LIMIT, UPPER_LIMIT FROM MAPLEMONK.REDTAPE_FLIPKART_RATE_CARD_COMMISSIONS) CMM ON LOWER(FKT.FLIPKART_CATEGORY) = LOWER(CMM.Vertical) AND LOWER(FKT.CATEGORY) = LOWER(CMM.CATEGORY) AND (FKT.BILL_VALUE - ifnull(NEW_GTA_VALUE,0)) BETWEEN CMM.lower_limit AND CMM.upper_limit LEFT JOIN ( SELECT VERTICAL,LOWER_WEIGHT,UPPER_WEIGHT,LOCAL,ZONAL,NATIONAL FROM MAPLEMONK.FLIPKART_REDTAPE_NEW_REVERSE_SHIPPING_MAPPING_OPEN UNION ALL SELECT VERTICAL,LOWER_WEIGHT,UPPER_WEIGHT,LOCAL,ZONAL,NATIONAL FROM MAPLEMONK.FLIPKART_REDTAPE_NEW_REVERSE_SHIPPING_MAPPING_CLOSED ) REV ON LOWER(FKT.FLIPKART_CATEGORY)=LOWER(REV.VERTICAL) AND FKT.CHARGEABLE_WEIGHT BETWEEN REV.LOWER_WEIGHT AND REV.UPPER_WEIGHT LEFT JOIN (SELECT REMARKS ,CAST(REPLACE(LOCAL,\'%\',\'\') AS FLOAT) LOCAL ,CAST(REPLACE(ZONAL,\'%\',\'\') AS FLOAT) ZONAL ,CAST(REPLACE(NATIONAL,\'%\',\'\') AS FLOAT) NATIONAL FROM MAPLEMONK.FLIPKART_REDTAPE_NEW_ZONES_SHARE__) ZS ON 1=1;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from REDTAPE_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            